1	import nodemailer from "nodemailer";
2	import { db } from "./db";
3	
4	/**
5	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
6	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
7	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
8	 */
9	async function loadSmtp() {
10	  const rows = await db.setting.findMany({
11	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
12	  });
13	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
14	  const host = s.smtp_host || process.env.SMTP_HOST || "";
15	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
16	  return {
17	    host,
18	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
19	    user: s.smtp_user || process.env.SMTP_USER || "",
20	    pass: s.smtp_pass || process.env.SMTP_PASS || "",
21	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
22	    from,
23	  };
24	}
25	
26	export async function mailConfigured(): Promise<boolean> {
27	  const c = await loadSmtp();
28	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
29	}
30	
31	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
32	  if (!c.host) {
33	    // Local MTA fallback (Postfix/sendmail on the host)
34	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
35	  }
36	  return nodemailer.createTransport({
37	    host: c.host,
38	    port: c.port,
39	    secure: c.secure,
40	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
41	  });
42	}
43	
44	/** Send an email. Never throws — logs and returns false on failure so callers don't break flows. */
45	export async function sendMail(opts: { to: string; subject: string; html: string; text?: string }): Promise<boolean> {
46	  try {
47	    const c = await loadSmtp();
48	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
49	      console.warn("[mailer] not configured — skipping email:", opts.subject);
50	      return false;
51	    }
52	    const t = transport(c);
53	    await t.sendMail({
54	      from: c.from,
55	      to: opts.to,
56	      subject: opts.subject,
57	      html: opts.html,
58	      text: opts.text ?? opts.html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
59	    });
60	    return true;
61	  } catch (e) {
62	    console.error("[mailer] send failed:", e);
63	    return false;
64	  }
65	}
66	
67	export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
68	  try {
69	    const c = await loadSmtp();
70	    const t = transport(c);
71	    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html: layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>") });
72	    return { ok: true };
73	  } catch (e: any) {
74	    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
75	  }
76	}
