import { db } from "@/lib/db";

/**
 * DB-backed email rendering.
 *
 * Templates live in the `EmailTemplate` table (admin-editable). Each row stores
 * a `subject` and an HTML *body* containing `{{variable}}` placeholders. At send
 * time we load the row, substitute the variables, and wrap the body in the
 * shared branded shell (header/footer). If a template is missing or disabled we
 * fall back to a minimal built-in default so a send never silently produces an
 * empty email.
 *
 * This module has NO dependency on `lib/mailer.ts` (mailer depends on it), which
 * keeps the import graph acyclic.
 */

const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };

export function appUrl(): string {
  return process.env.APP_URL ?? "https://revsports.ca";
}

/** Shared responsive email shell (inline styles for client compatibility). */
export function wrapEmail(bodyHtml: string): string {
  const url = appUrl();
  return `<!doctype html><html><body style="margin:0;background:${BRAND.bg};font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#e2e8f0">
  <div style="max-width:560px;margin:0 auto;padding:32px 20px">
    <div style="text-align:center;margin-bottom:24px">
      <img src="${url}/logo.png" alt="Nxeon" height="34" style="height:34px;width:auto" />
    </div>
    <div style="background:${BRAND.card};border:1px solid rgba(255,255,255,0.06);border-radius:16px;padding:28px;font-size:14px;line-height:1.6;color:#cbd5e1">
      ${bodyHtml}
    </div>
    <p style="text-align:center;color:#64748b;font-size:12px;margin-top:20px">
      <a href="${url}" style="color:${BRAND.purple};text-decoration:none">Nxeon Cloud</a> · High-performance VPS hosting
      <br/><span style="color:#475569">You received this because you have a Nxeon account.</span>
    </p>
  </div></body></html>`;
}

/** Branded CTA button (inline styles). */
export function emailButton(href: string, label: string): string {
  return `<a href="${href}" style="display:inline-block;margin:16px 0;padding:11px 22px;border-radius:12px;background:linear-gradient(90deg,${BRAND.blue},${BRAND.purple});color:#fff;font-weight:600;text-decoration:none;font-size:14px">${label}</a>`;
}

/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
export function substitute(input: string, vars: Record<string, unknown>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
    const v = vars[key];
    return v === undefined || v === null ? "" : String(v);
  });
}

/**
 * Minimal built-in defaults used when a template row is missing or disabled.
 * These are intentionally plain — the real, branded copy lives in the DB (see
 * `prisma/seed-email-templates.ts`).
 */
const DEFAULTS: Record<string, { subject: string; body: string }> = {
  welcome: {
    subject: "Welcome to Nxeon",
    body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Welcome, {{name}}!</h1><p>Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.</p>`,
  },
  password_reset: {
    subject: "Reset your Nxeon password",
    body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Reset your password</h1><p>Use the link below to set a new password. It expires in 1 hour.</p><p><a href="{{resetUrl}}" style="color:#8a70fb">{{resetUrl}}</a></p>`,
  },
};

const GENERIC_FALLBACK = (key: string) => ({
  subject: "A message from Nxeon",
  body: `<h1 style="margin:0 0 14px;font-size:19px;color:#fff">Nxeon</h1><p>This notification (<code>${key}</code>) has no configured template.</p>`,
});

export type RenderedEmail = { subject: string; html: string; template: string };

/**
 * Render a stored (or default) template for `key`, substituting `vars`,
 * returning the final subject and full wrapped HTML ready to send/preview.
 */
export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
  let subject: string;
  let body: string;

  let row: { subject: string; html: string; enabled: boolean } | null = null;
  try {
    row = await db.emailTemplate.findUnique({
      where: { key },
      select: { subject: true, html: true, enabled: true },
    });
  } catch {
    row = null;
  }

  if (row && row.enabled) {
    subject = row.subject;
    body = row.html;
  } else {
    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
    subject = d.subject;
    body = d.body;
  }

  return {
    template: key,
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars)),
  };
}

/**
 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
 * editor's live preview and by the seed preview. Same wrapping as a real send.
 */
export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
  return {
    template: "draft",
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars)),
  };
}

/**
 * Append an `EmailLog` row for every send attempt. Never throws (logging must
 * not break a mail flow).
 */
export async function recordEmail(
  toEmail: string,
  subject: string,
  template: string | null,
  html: string,
  status: "SENT" | "FAILED",
  error?: string | null,
  userId?: string | null,
): Promise<void> {
  try {
    await db.emailLog.create({
      data: {
        toEmail,
        subject: subject.slice(0, 500),
        template: template ?? null,
        html,
        status,
        error: error ? String(error).slice(0, 1000) : null,
        userId: userId ?? null,
      },
    });
  } catch (e) {
    console.error("[email-render] failed to record EmailLog:", e);
  }
}

/**
 * Seed the DB-backed, admin-editable email templates.
 *
 * Each template stores a `subject` and an HTML *body* (the body is wrapped in
 * the shared branded shell at render time — see `lib/email-render.ts`). Bodies
 * use `{{variable}}` placeholders. Run with:
