function btn(href: string, label: string): string {
  return `<a href="${href}" style="display:inline-block;margin:16px 0;padding:11px 22px;border-radius:12px;background:linear-gradient(90deg,${BLUE},${PURPLE});color:#fff;font-weight:600;text-decoration:none;font-size:14px">${label}</a>`;
}
function h1(text: string): string {
  return `<h1 style="margin:0 0 16px;font-size:19px;color:#fff">${text}</h1>`;
}
/** Monospace fact box (SSH commands, codes, IPs). */
function code(text: string): string {
  return `<p style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#0a101f;border:1px solid rgba(255,255,255,0.06);padding:12px;border-radius:10px;color:#e2e8f0;word-break:break-all">${text}</p>`;
}
/** Key/value detail rows. */
function facts(rows: [string, string][]): string {
  return `<table style="width:100%;border-collapse:collapse;margin:12px 0">${rows
    .map(
      ([k, v]) =>
        `<tr><td style="padding:6px 0;color:#94a3b8;font-size:13px">${k}</td><td style="padding:6px 0;text-align:right;color:#e2e8f0;font-weight:600">${v}</td></tr>`,
    )
    .join("")}</table>`;
}
function muted(text: string): string {
  return `<p style="font-size:12px;color:#64748b;margin-top:16px">${text}</p>`;
}

