"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import {
  listEmailTemplates,
  saveEmailTemplate,
  toggleEmailTemplate,
  resetEmailTemplate,
  type EmailTemplateDTO,
} from "@/lib/actions-email-templates";

/**
 * Admin editor for DB-backed email templates.
 *
 * Left rail groups templates by category; the main pane edits subject + HTML
 * body, toggles enabled, shows a live sandboxed preview and a {{variable}}
 * cheatsheet auto-extracted from the current draft. Wire-compatible whether the
 * host passes `templates` or lets the editor self-load.
 */

// Mirror of lib/email-render `wrapEmail` for instant client-side preview.
const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
function wrapPreview(bodyHtml: string): string {
  return `<!doctype html><html><body style="margin:0;background:${BRAND.bg};font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#e2e8f0">
  <div style="max-width:560px;margin:0 auto;padding:32px 20px">
    <div style="text-align:center;margin-bottom:24px;font-weight:800;font-size:20px;color:#fff">Nxeon</div>
    <div style="background:${BRAND.card};border:1px solid rgba(255,255,255,0.06);border-radius:16px;padding:28px;font-size:14px;line-height:1.6;color:#cbd5e1">${bodyHtml}</div>
    <p style="text-align:center;color:#64748b;font-size:12px;margin-top:20px">Nxeon Cloud · High-performance VPS hosting</p>
  </div></body></html>`;
}

// Representative sample values used only for the preview render.
const SAMPLE: Record<string, string> = {
  name: "Alex Rivera",
  dashboardUrl: "https://revsports.ca/dashboard",
  verifyUrl: "https://revsports.ca/verify?token=SAMPLE",
  resetUrl: "https://revsports.ca/reset-password?token=SAMPLE",
  code: "482913",
  time: "Jul 23, 2026 14:02 UTC",
  ip: "203.0.113.42",
  hostname: "mc-survival-01",
  sshCommand: "ssh root@51.79.162.96 -p 20144",
  manageUrl: "https://revsports.ca/dashboard/servers",
  billingUrl: "https://revsports.ca/dashboard/billing",
  renewUrl: "https://revsports.ca/dashboard/billing",
  expiryDate: "Aug 20, 2026",
  renewDate: "Aug 3, 2026",
  amount: "$12.00",
  description: "VPS Nebula — 1 month",
  invoiceNumber: "00042",
  invoiceUrl: "https://revsports.ca/dashboard/invoices",
  dueDate: "Aug 1, 2026",
  reason: "Card declined",
  daysOverdue: "3",
  couponCode: "LAUNCH25",
  discount: "25%",
  domain: "example.com",
  tokenName: "CI deploy key",
  referralName: "Jordan P.",
  walletUrl: "https://revsports.ca/dashboard/billing",
  ticketSubject: "Cannot connect via SSH",
  ticketId: "1042",
  replyPreview: "Thanks for reaching out — please try regenerating your SSH key…",
  ticketUrl: "https://revsports.ca/dashboard/support",
};

function extractVars(...sources: string[]): string[] {
  const set = new Set<string>();
  const re = /\{\{\s*([\w.]+)\s*\}\}/g;
  for (const s of sources) {
    let m: RegExpExecArray | null;
    while ((m = re.exec(s ?? ""))) set.add(m[1]);
  }
  return [...set];
}

function substitute(input: string, vars: Record<string, string>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, k: string) => vars[k] ?? `{{${k}}}`);
}

export function EmailTemplateEditor({ templates: initial }: { templates?: EmailTemplateDTO[] }) {
  const [templates, setTemplates] = useState<EmailTemplateDTO[]>(initial ?? []);
  const [loading, setLoading] = useState(!initial);
  const [activeKey, setActiveKey] = useState<string>(initial?.[0]?.key ?? "");

  // Draft state for the active template.
  const [subject, setSubject] = useState("");
  const [html, setHtml] = useState("");
  const [enabled, setEnabled] = useState(true);
  const [dirty, setDirty] = useState(false);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [pending, startTransition] = useTransition();

  useEffect(() => {
    if (initial) return;
    let alive = true;
    listEmailTemplates()
      .then((rows) => {
        if (!alive) return;
        setTemplates(rows);
        setActiveKey((k) => k || rows[0]?.key || "");
        setLoading(false);
      })
      .catch(() => setLoading(false));
    return () => {
      alive = false;
    };
  }, [initial]);

  const active = useMemo(() => templates.find((t) => t.key === activeKey) ?? null, [templates, activeKey]);

  // Load draft when the active template changes.
  useEffect(() => {
    if (!active) return;
    setSubject(active.subject);
    setHtml(active.html);
    setEnabled(active.enabled);
    setDirty(false);
    setMsg(null);
  }, [active?.key]); // eslint-disable-line react-hooks/exhaustive-deps

  const grouped = useMemo(() => {
    const map = new Map<string, EmailTemplateDTO[]>();
    for (const t of templates) {
      const arr = map.get(t.category) ?? [];
      arr.push(t);
      map.set(t.category, arr);
    }
    return [...map.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  }, [templates]);

  const vars = useMemo(() => extractVars(subject, html), [subject, html]);
  const previewDoc = useMemo(() => wrapPreview(substitute(html, SAMPLE)), [html]);
  const previewSubject = useMemo(() => substitute(subject, SAMPLE), [subject]);

  function patchLocal(key: string, patch: Partial<EmailTemplateDTO>) {
    setTemplates((prev) => prev.map((t) => (t.key === key ? { ...t, ...patch } : t)));
  }

  function onSave() {
    if (!active) return;
    setMsg(null);
    startTransition(async () => {
      const res = await saveEmailTemplate({ key: active.key, subject, html });
      if (res.ok) {
        patchLocal(active.key, { subject, html });
        setDirty(false);
        setMsg({ ok: true, text: "Saved." });
      } else {
        setMsg({ ok: false, text: res.error ?? "Save failed." });
      }
    });
  }

  function onToggle() {
    if (!active) return;
    const next = !enabled;
    setEnabled(next);
    startTransition(async () => {
      const res = await toggleEmailTemplate(active.key, next);
      if (res.ok) patchLocal(active.key, { enabled: next });
      else {
        setEnabled(!next);
        setMsg({ ok: false, text: res.error ?? "Toggle failed." });
      }
    });
  }

  function onReset() {
    if (!active) return;
    if (!confirm(`Reset "${active.name}" to the built-in default? Your edits will be overwritten.`)) return;
    startTransition(async () => {
      const res = await resetEmailTemplate(active.key);
      if (res.ok && res.template) {
        patchLocal(active.key, res.template);
        setSubject(res.template.subject);
        setHtml(res.template.html);
        setEnabled(res.template.enabled);
        setDirty(false);
        setMsg({ ok: true, text: "Restored to default." });
      } else {
        setMsg({ ok: false, text: res.error ?? "Reset failed." });
      }
    });
  }

  if (loading) return <div className="card p-6 text-sm text-slate-400">Loading templates…</div>;
  if (!templates.length) return <div className="card p-6 text-sm text-slate-400">No email templates found. Run the seed.</div>;

  return (
    <div className="grid gap-5 lg:grid-cols-[240px_1fr]">
      {/* Left rail */}
      <div className="card h-fit p-2">
        {grouped.map(([cat, items]) => (
          <div key={cat} className="mb-2">
            <p className="section-label px-2 pb-1 pt-2">{cat}</p>
            <div className="space-y-0.5">
              {items.map((t) => (
                <button
                  key={t.key}
                  onClick={() => setActiveKey(t.key)}
                  className={`nav-item w-full text-left ${t.key === activeKey ? "nav-item-active" : ""}`}
                >
                  <span className="flex-1 truncate">{t.name}</span>
                  {!t.enabled && <span className="text-[10px] uppercase text-amber-400">off</span>}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Editor + preview */}
      {active && (
        <div className="space-y-4">
          <div className="card p-5">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div>
                <h3 className="text-base font-semibold text-white">{active.name}</h3>
                <code className="font-mono text-xs text-brand-300">{active.key}</code>
                <span className="ml-2 text-xs text-slate-500">· {active.category}</span>
              </div>
              <div className="flex items-center gap-2">
                <label className="flex cursor-pointer items-center gap-2 text-xs text-slate-300">
                  <input type="checkbox" checked={enabled} onChange={onToggle} disabled={pending} className="accent-brand-500" />
                  Enabled
                </label>
                <button onClick={onReset} disabled={pending} className="btn-ghost text-xs">
                  Reset to default
                </button>
              </div>
            </div>

            <div className="mt-4">
              <label className="label">Subject</label>
              <input
                className="input"
                value={subject}
                onChange={(e) => {
                  setSubject(e.target.value);
                  setDirty(true);
                }}
              />
            </div>

            <div className="mt-4">
              <label className="label">HTML body (wrapped in the branded shell at send time)</label>
              <textarea
                className="input font-mono text-xs"
                rows={14}
                spellCheck={false}
                value={html}
                onChange={(e) => {
                  setHtml(e.target.value);
                  setDirty(true);
                }}
              />
            </div>

            {/* Variable cheatsheet */}
            <div className="mt-4">
              <p className="section-label">Variables in this template</p>
              <div className="mt-1.5 flex flex-wrap gap-1.5">
                {vars.length ? (
                  vars.map((v) => (
                    <button
                      key={v}
                      type="button"
                      title="Insert at end of body"
                      onClick={() => {
                        setHtml((h) => `${h}{{${v}}}`);
                        setDirty(true);
                      }}
                      className="kbd hover:text-brand-300"
                    >
                      {"{{"}
                      {v}
                      {"}}"}
                    </button>
                  ))
                ) : (
                  <span className="text-xs text-slate-500">No {"{{variables}}"} used.</span>
                )}
              </div>
            </div>

            <div className="mt-5 flex items-center gap-3">
              <button onClick={onSave} disabled={pending || !dirty} className="btn-primary">
                {pending ? "Saving…" : "Save changes"}
              </button>
              {dirty && <span className="text-xs text-amber-400">Unsaved changes</span>}
              {msg && <span className={`text-xs ${msg.ok ? "text-emerald-400" : "text-red-400"}`}>{msg.text}</span>}
            </div>
          </div>

          {/* Live preview */}
          <div className="card overflow-hidden p-0">
            <div className="flex items-center justify-between border-b border-white/[0.06] px-4 py-2.5">
              <div>
                <p className="text-xs font-medium text-slate-400">Live preview</p>
                <p className="mt-0.5 text-sm font-semibold text-white">{previewSubject}</p>
              </div>
              <p className="text-[11px] text-slate-600">sandboxed · sample data</p>
            </div>
            <iframe
              title={`${active.name} preview`}
              srcDoc={previewDoc}
              sandbox=""
              className="h-[560px] w-full border-0 bg-white"
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default EmailTemplateEditor;

"use client";

import { useState } from "react";
import { Badge } from "@/components/ui/primitives";

export type EmailLogRow = {
  id: string;
  toEmail: string;
  subject: string;
  template: string | null;
  status: string;
  error: string | null;
  html: string;
  createdAt: string; // ISO
};

function fmt(iso: string): string {
  return iso.replace("T", " ").slice(0, 19);
}

/**
 * Admin viewer for sent/failed emails. A table of recent messages with a
 * per-row "Preview" that renders the stored HTML inside a sandboxed iframe.
 */
export function EmailLogViewer({ logs }: { logs: EmailLogRow[] }) {
  const [preview, setPreview] = useState<EmailLogRow | null>(null);

  if (!logs.length) {
    return (
      <div className="card p-6 text-sm text-slate-400">
        No emails have been sent yet. They&apos;ll appear here the moment Nxeon dispatches one.
      </div>
    );
  }

  return (
    <>
      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Time</th>
              <th>To</th>
              <th>Subject</th>
              <th>Template</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {logs.map((l) => (
              <tr key={l.id}>
                <td className="whitespace-nowrap text-slate-400">{fmt(l.createdAt)}</td>
                <td className="whitespace-nowrap">{l.toEmail}</td>
                <td className="max-w-xs truncate">{l.subject}</td>
                <td>
                  {l.template ? (
                    <code className="font-mono text-xs text-brand-300">{l.template}</code>
                  ) : (
                    <span className="text-slate-600">—</span>
                  )}
                </td>
                <td>
                  {l.status === "SENT" ? (
                    <Badge tone="green">sent</Badge>
                  ) : (
                    <Badge tone="red">failed</Badge>
                  )}
                  {l.error && <span className="ml-2 text-xs text-red-400/80" title={l.error}>{l.error.slice(0, 40)}</span>}
                </td>
                <td className="text-right">
                  <button onClick={() => setPreview(l)} className="btn-ghost text-xs">
                    Preview
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {preview && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"
          onClick={() => setPreview(null)}
        >
          <div
            className="card flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden p-0"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-start justify-between gap-4 border-b border-white/[0.06] px-5 py-3">
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-white">{preview.subject}</p>
                <p className="mt-0.5 truncate text-xs text-slate-500">
                  To {preview.toEmail} · {fmt(preview.createdAt)}
                  {preview.template ? ` · ${preview.template}` : ""}
                </p>
              </div>
              <button onClick={() => setPreview(null)} className="btn-ghost text-xs">
                Close
              </button>
            </div>
            {preview.error && (
              <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
                {preview.error}
              </div>
            )}
            <iframe
              title="Email preview"
              srcDoc={preview.html}
              sandbox=""
              className="w-full flex-1 border-0 bg-white"
            />
          </div>
        </div>
      )}
    </>
  );
}

export default EmailLogViewer;

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { EmailLogViewer, type EmailLogRow } from "@/components/admin/EmailLogViewer";

export const dynamic = "force-dynamic";

type Tab = "audit" | "activity" | "email";
const TABS: { key: Tab; label: string }[] = [
  { key: "audit", label: "Audit" },
  { key: "activity", label: "Activity" },
  { key: "email", label: "Email" },
];

export default async function AdminLogs({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string }>;
}) {
  await requireArea("platform");
  const sp = await searchParams;
  const tab: Tab = (["audit", "activity", "email"] as const).includes(sp.tab as Tab)
    ? (sp.tab as Tab)
    : "audit";

  return (
    <div className="space-y-6">
      <PageHeader title="Logs" sub="Audit trail, platform activity, and outbound email">
        <Badge tone="slate">platform</Badge>
      </PageHeader>

      {/* Tabs */}
      <div className="flex gap-1 rounded-xl border border-white/[0.06] bg-white/[0.02] p-1">
        {TABS.map((t) => (
          <Link
            key={t.key}
            href={`/admin/logs?tab=${t.key}`}
            className={`rounded-lg px-4 py-1.5 text-sm font-medium transition-colors ${
              tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            {t.label}
          </Link>
        ))}
      </div>

      {tab === "audit" && <AuditTab />}
      {tab === "activity" && <ActivityTab />}
      {tab === "email" && <EmailTab />}
    </div>
  );
}

/* ---------------- Audit ---------------- */

async function AuditTab() {
  const logs = await db.auditLog.findMany({
    include: { user: { select: { email: true, id: true } } },
    orderBy: { createdAt: "desc" },
    take: 200,
  });

  return (
    <div className="card overflow-x-auto p-0">
      <table className="table-shell">
        <thead>
          <tr>
            <th>Time</th>
            <th>Actor</th>
            <th>Action</th>
            <th>Detail</th>
          </tr>
        </thead>
        <tbody>
          {logs.map((l) => (
            <tr key={l.id}>
              <td className="whitespace-nowrap text-slate-400">
                {l.createdAt.toISOString().replace("T", " ").slice(0, 19)}
              </td>
              <td>
                {l.user ? (
                  <Link href={`/admin/users/${l.user.id}`} className="hover:text-brand-300">
                    {l.user.email}
                  </Link>
                ) : (
                  <span className="text-slate-500">system</span>
                )}
              </td>
              <td className="font-mono text-xs">{l.action}</td>
              <td className="max-w-md truncate text-slate-400">{l.detail}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ---------------- Activity feed ---------------- */

type Activity = {
  id: string;
  at: Date;
  kind: "audit" | "payment" | "job";
  tone: "brand" | "green" | "amber" | "slate" | "red";
  label: string;
  text: string;
  actor?: string | null;
};

async function ActivityTab() {
  const [audits, txns, jobs] = await Promise.all([
    db.auditLog.findMany({
      include: { user: { select: { email: true } } },
      orderBy: { createdAt: "desc" },
      take: 40,
    }),
    db.walletTransaction.findMany({
      include: { user: { select: { email: true } } },
      orderBy: { createdAt: "desc" },
      take: 40,
    }),
    db.job.findMany({ orderBy: { createdAt: "desc" }, take: 40 }),
  ]);

  const items: Activity[] = [];

  for (const a of audits) {
    items.push({
      id: `a-${a.id}`,
      at: a.createdAt,
      kind: "audit",
      tone: a.action.startsWith("admin.") ? "amber" : "brand",
      label: a.action,
      text: a.detail ?? "",
      actor: a.user?.email ?? "system",
    });
  }
  for (const t of txns) {
    const credit = t.amountCents >= 0;
    items.push({
      id: `t-${t.id}`,
      at: t.createdAt,
      kind: "payment",
      tone: credit ? "green" : "slate",
      label: credit ? "wallet.credit" : "wallet.debit",
      text: `${fmtMoney(t.amountCents)} · ${t.description}`,
      actor: t.user?.email ?? null,
    });
  }
  for (const j of jobs) {
    items.push({
      id: `j-${j.id}`,
      at: j.createdAt,
      kind: "job",
      tone: j.status === "FAILED" ? "red" : j.status === "DONE" ? "green" : "slate",
      label: `job.${String(j.type).toLowerCase()}`,
      text: `${j.status}${j.error ? ` · ${j.error}` : ""}`,
      actor: null,
    });
  }

  items.sort((a, b) => b.at.getTime() - a.at.getTime());
  const feed = items.slice(0, 80);

  return (
    <div className="card divide-y divide-white/[0.05] p-0">
      {feed.map((it) => (
        <div key={it.id} className="flex items-start gap-3 px-4 py-3">
          <Badge tone={it.tone}>{it.kind}</Badge>
          <div className="min-w-0 flex-1">
            <p className="text-sm">
              <code className="font-mono text-xs text-brand-300">{it.label}</code>
              {it.text && <span className="ml-2 text-slate-300">{it.text}</span>}
            </p>
            {it.actor && <p className="mt-0.5 text-xs text-slate-500">{it.actor}</p>}
          </div>
          <span className="whitespace-nowrap text-xs text-slate-500" title={it.at.toISOString()}>
            {timeAgo(it.at)}
          </span>
        </div>
      ))}
    </div>
  );
}

/* ---------------- Email ---------------- */

async function EmailTab() {
  const rows = await db.emailLog.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
  const logs: EmailLogRow[] = rows.map((r) => ({
    id: r.id,
    toEmail: r.toEmail,
    subject: r.subject,
    template: r.template,
    status: r.status,
    error: r.error,
    html: r.html,
    createdAt: r.createdAt.toISOString(),
  }));
  return <EmailLogViewer logs={logs} />;
}
